const input = $json.body ?? $json;

const text = (value) =>
  value === null || value === undefined
    ? ''
    : String(value).trim();

const bool = (value) =>
  typeof value === 'boolean'
    ? value
    : ['true', '1', 'yes', 'on'].includes(
        text(value).toLowerCase()
      );

const clinic_name = text(input.clinic_name);
const mobile = text(input.mobile);
const channel = text(input.channel).toLowerCase();
const purpose = text(input.purpose).toLowerCase();
const requested_at = text(input.requested_at);
const request_reference = text(input.request_reference);
const confirm_check = bool(input.confirm_check);

const channels = [
  'whatsapp',
  'sms',
  'email',
  'phone',
  'web_push',
  'in_app',
];

const purposes = [
  'appointment_reminder',
  'appointment_update',
  'waitlist_offer',
  'post_visit_followup',
  'clinical_followup',
  'marketing',
  'satisfaction_survey',
  'general_information',
  'human_handoff',
];

const errors = [];

if (!clinic_name) {
  errors.push({
    field: 'clinic_name',
    message: 'نام کلینیک الزامی است.',
  });
}

if (!/^\+?[0-9]{8,15}$/.test(mobile)) {
  errors.push({
    field: 'mobile',
    message: 'شماره موبایل معتبر نیست.',
  });
}

if (!channels.includes(channel)) {
  errors.push({
    field: 'channel',
    message: 'کانال ارتباطی معتبر نیست.',
  });
}

if (!purposes.includes(purpose)) {
  errors.push({
    field: 'purpose',
    message: 'هدف پیام معتبر نیست.',
  });
}

if (
  requested_at &&
  Number.isNaN(Date.parse(requested_at))
) {
  errors.push({
    field: 'requested_at',
    message: 'زمان درخواست معتبر نیست.',
  });
}

if (confirm_check !== true) {
  errors.push({
    field: 'confirm_check',
    message: 'بررسی مجوز باید تأیید شود.',
  });
}

return [{
  json: {
    clinic_name,
    mobile,
    channel,
    purpose,
    requested_at:
      requested_at || new Date().toISOString(),
    request_reference,
    confirm_check,
    validation_status:
      errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];

if ($json.success !== true) {
  return [{
    json: {
      success: false,
      result: $json.result || 'permission_context_failed',
      decision: 'error',
      decision_reason: 'patient_not_found',
      allowed: false,
      deferred: false,
    },
  }];
}

const patient = $json.patient_context || {};
const consents =
  $json.consent_snapshot &&
  typeof $json.consent_snapshot === 'object'
    ? $json.consent_snapshot
    : {};

const preference =
  $json.preference_snapshot &&
  typeof $json.preference_snapshot === 'object'
    ? $json.preference_snapshot
    : {};

const statusOf = (type) =>
  consents[type]?.status || 'missing';

const requiredConsentByPurpose = {
  appointment_reminder: 'appointment_reminders',
  appointment_update: null,
  waitlist_offer: null,
  post_visit_followup: 'followup_messages',
  clinical_followup: 'followup_messages',
  marketing: 'marketing_messages',
  satisfaction_survey: 'satisfaction_surveys',
  general_information: null,
  human_handoff: null,
};

let decision = 'allowed';
let decisionReason = 'permission_granted';
let nextAllowedAt = null;

const contactStatus = statusOf('contact');
const specificConsent =
  requiredConsentByPurpose[patient.purpose];

if (contactStatus !== 'granted') {
  decision = 'blocked';
  decisionReason =
    contactStatus === 'revoked'
      ? 'contact_consent_revoked'
      : (
          contactStatus === 'expired'
            ? 'contact_consent_expired'
            : 'contact_consent_missing'
        );
}

if (
  decision === 'allowed' &&
  specificConsent &&
  statusOf(specificConsent) !== 'granted'
) {
  const status = statusOf(specificConsent);
  decision = 'blocked';
  decisionReason =
    status === 'revoked'
      ? `${specificConsent}_revoked`
      : (
          status === 'expired'
            ? `${specificConsent}_expired`
            : `${specificConsent}_missing`
        );
}

if (
  decision === 'allowed' &&
  preference.enabled === false
) {
  decision = 'blocked';
  decisionReason = 'channel_disabled_by_patient';
}

const timezone =
  preference.timezone || 'Asia/Baghdad';

const requestedAt = new Date(
  patient.requested_at || Date.now()
);

const timeParts = new Intl.DateTimeFormat(
  'en-GB',
  {
    timeZone: timezone,
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23',
  }
).formatToParts(requestedAt);

const hour = Number(
  timeParts.find((part) => part.type === 'hour')?.value || 0
);
const minute = Number(
  timeParts.find((part) => part.type === 'minute')?.value || 0
);
const localMinutes = hour * 60 + minute;

const toMinutes = (value) => {
  const match = String(value || '').match(
    /^(\d{1,2}):(\d{2})/
  );

  if (!match) return null;

  return Number(match[1]) * 60 + Number(match[2]);
};

const quietStart =
  toMinutes(preference.quiet_hours_start);
const quietEnd =
  toMinutes(preference.quiet_hours_end);

const inQuietHours = (
  preference.quiet_hours_enabled === true &&
  quietStart !== null &&
  quietEnd !== null &&
  (
    quietStart < quietEnd
      ? (
          localMinutes >= quietStart &&
          localMinutes < quietEnd
        )
      : (
          localMinutes >= quietStart ||
          localMinutes < quietEnd
        )
  )
);

if (
  decision === 'allowed' &&
  inQuietHours
) {
  decision = 'deferred';
  decisionReason = 'patient_quiet_hours';
}

return [{
  json: {
    success: true,
    result: 'communication_permission_checked',
    clinic_id: Number(patient.clinic_id),
    patient_id: Number(patient.patient_id),
    mobile: patient.mobile,
    channel: patient.channel,
    purpose: patient.purpose,
    requested_at: patient.requested_at,
    request_reference:
      patient.request_reference || '',
    decision,
    decision_reason: decisionReason,
    allowed: decision === 'allowed',
    deferred: decision === 'deferred',
    next_allowed_at: nextAllowedAt,
    max_messages_per_week:
      preference.max_messages_per_week ?? null,
    timezone,
    consent_snapshot: consents,
    consent_snapshot_text:
      JSON.stringify(consents),
    preference_snapshot: preference,
    preference_snapshot_text:
      JSON.stringify(preference),
  },
}];
